Index: cmd/textconv/main.go
===================================================================
--- cmd/textconv/main.go	
+++ cmd/textconv/main.go	
@@ -0,0 +1,74 @@
+// Command textconv converts text between character encodings and applies
+// Unicode normalization.
+//
+// Usage:
+//
+//	textconv -from windows-1252 -to utf-8 -normalize NFC [file]
+//
+// With no file, or with "-", it reads from standard input and writes to
+// standard output.
+package main
+
+import (
+	"flag"
+	"fmt"
+	"io"
+	"os"
+
+	"example.com/textconv"
+)
+
+func main() {
+	if err := run(); err != nil {
+		fmt.Fprintln(os.Stderr, "textconv:", err)
+		os.Exit(1)
+	}
+}
+
+func run() error {
+	from := flag.String("from", "utf-8", "source encoding")
+	to := flag.String("to", "utf-8", "destination encoding")
+	form := flag.String("normalize", "", "Unicode normalization form (NFC, NFD, NFKC, NFKD)")
+	list := flag.Bool("list", false, "list supported encodings and exit")
+	flag.Parse()
+
+	if *list {
+		for _, name := range textconv.Names() {
+			fmt.Println(name)
+		}
+		return nil
+	}
+
+	n, err := textconv.ParseNormalization(*form)
+	if err != nil {
+		return err
+	}
+
+	in, err := openInput(flag.Arg(0))
+	if err != nil {
+		return err
+	}
+	defer in.Close()
+
+	src, err := textconv.NewReader(in, *from)
+	if err != nil {
+		return err
+	}
+
+	dst, err := textconv.NewWriter(os.Stdout, *to, n)
+	if err != nil {
+		return err
+	}
+
+	if _, err := io.Copy(dst, src); err != nil {
+		return err
+	}
+	return dst.Close()
+}
+
+func openInput(path string) (io.ReadCloser, error) {
+	if path == "" || path == "-" {
+		return io.NopCloser(os.Stdin), nil
+	}
+	return os.Open(path)
+}

Index: textconv.go
===================================================================
--- textconv.go	
+++ textconv.go	
@@ -0,0 +1,88 @@
+// Package textconv converts text between character encodings and applies
+// Unicode normalization.
+//
+// It builds on golang.org/x/text: decoding turns bytes in a source encoding
+// into UTF-8, normalization operates on that UTF-8, and encoding turns UTF-8
+// into the destination encoding.
+package textconv
+
+import (
+	"fmt"
+	"io"
+
+	"golang.org/x/text/encoding"
+	"golang.org/x/text/transform"
+)
+
+// Decode converts data from the named source encoding into UTF-8. Invalid
+// input sequences are replaced with U+FFFD.
+func Decode(data []byte, src string) ([]byte, error) {
+	enc, err := Lookup(src)
+	if err != nil {
+		return nil, err
+	}
+	return decode(data, enc)
+}
+
+func decode(data []byte, enc encoding.Encoding) ([]byte, error) {
+	out, _, err := transform.Bytes(enc.NewDecoder(), data)
+	if err != nil {
+		return nil, fmt.Errorf("textconv: decode: %w", err)
+	}
+	return out, nil
+}
+
+// Encode converts UTF-8 text into the named destination encoding. Runes that
+// cannot be represented are replaced with the encoding's substitution, usually
+// '?'.
+func Encode(utf8 []byte, dst string) ([]byte, error) {
+	enc, err := Lookup(dst)
+	if err != nil {
+		return nil, err
+	}
+	return encode(utf8, enc)
+}
+
+func encode(utf8 []byte, enc encoding.Encoding) ([]byte, error) {
+	out, _, err := transform.Bytes(encoding.ReplaceUnsupported(enc.NewEncoder()), utf8)
+	if err != nil {
+		return nil, fmt.Errorf("textconv: encode: %w", err)
+	}
+	return out, nil
+}
+
+// Convert decodes data from the from encoding, normalizes it to n (when n is
+// not None), and encodes the result as to.
+func Convert(data []byte, from, to string, n Normalization) ([]byte, error) {
+	utf8, err := Decode(data, from)
+	if err != nil {
+		return nil, err
+	}
+	if n != None {
+		utf8 = []byte(Normalize(string(utf8), n))
+	}
+	return Encode(utf8, to)
+}
+
+// NewReader returns a reader that decodes the underlying stream from src into
+// UTF-8.
+func NewReader(r io.Reader, src string) (io.Reader, error) {
+	enc, err := Lookup(src)
+	if err != nil {
+		return nil, err
+	}
+	return transform.NewReader(r, enc.NewDecoder()), nil
+}
+
+// NewWriter returns a writer that normalizes UTF-8 input to n and encodes it
+// as dst before writing to w. Callers must call Close to flush trailing bytes.
+func NewWriter(w io.Writer, dst string, n Normalization) (io.WriteCloser, error) {
+	enc, err := Lookup(dst)
+	if err != nil {
+		return nil, err
+	}
+	if n == None {
+		return transform.NewWriter(w, encoding.ReplaceUnsupported(enc.NewEncoder())), nil
+	}
+	return transform.NewWriter(w, transform.Chain(n.form(), encoding.ReplaceUnsupported(enc.NewEncoder()))), nil
+}

Index: textconv_test.go
===================================================================
--- textconv_test.go	
+++ textconv_test.go	
@@ -0,0 +1,146 @@
+package textconv
+
+import (
+	"bytes"
+	"io"
+	"strings"
+	"testing"
+)
+
+func TestLookup(t *testing.T) {
+	want, err := Lookup("utf-8")
+	if err != nil {
+		t.Fatalf("Lookup(utf-8): %v", err)
+	}
+	for _, name := range []string{"UTF_8", "utf8", "  Utf-8  "} {
+		got, err := Lookup(name)
+		if err != nil {
+			t.Errorf("Lookup(%q): %v", name, err)
+			continue
+		}
+		if got != want {
+			t.Errorf("Lookup(%q) != Lookup(utf-8)", name)
+		}
+	}
+	if _, err := Lookup("no-such-encoding"); err == nil {
+		t.Error("Lookup(no-such-encoding) succeeded, want error")
+	}
+}
+
+func TestNamesSorted(t *testing.T) {
+	names := Names()
+	if len(names) == 0 {
+		t.Fatal("Names returned nothing")
+	}
+	for i := 1; i < len(names); i++ {
+		if names[i-1] >= names[i] {
+			t.Fatalf("Names not sorted: %q before %q", names[i-1], names[i])
+		}
+	}
+}
+
+func TestDecode(t *testing.T) {
+	// 0x80 is the euro sign in Windows-1252.
+	got, err := Decode([]byte{0x80}, "windows-1252")
+	if err != nil {
+		t.Fatalf("Decode: %v", err)
+	}
+	if want := "\u20ac"; string(got) != want {
+		t.Errorf("Decode = %q, want %q", got, want)
+	}
+}
+
+func TestEncode(t *testing.T) {
+	got, err := Encode([]byte("café"), "iso-8859-1")
+	if err != nil {
+		t.Fatalf("Encode: %v", err)
+	}
+	if want := []byte{'c', 'a', 'f', 0xe9}; !bytes.Equal(got, want) {
+		t.Errorf("Encode = % x, want % x", got, want)
+	}
+}
+
+func TestConvert(t *testing.T) {
+	// NFD "e" + combining acute, supplied as UTF-8, composed to NFC.
+	got, err := Convert([]byte("e\u0301"), "utf-8", "utf-8", NFC)
+	if err != nil {
+		t.Fatalf("Convert: %v", err)
+	}
+	if want := "\u00e9"; string(got) != want {
+		t.Errorf("Convert = %q, want %q", got, want)
+	}
+}
+
+func TestNormalize(t *testing.T) {
+	tests := []struct {
+		name string
+		in   string
+		form Normalization
+		want string
+	}{
+		{"none keeps input", "e\u0301", None, "e\u0301"},
+		{"nfc composes", "e\u0301", NFC, "\u00e9"},
+		{"nfd decomposes", "\u00e9", NFD, "e\u0301"},
+		{"nfkc composes", "\u00e9", NFKC, "\u00e9"},
+		{"nfkc folds ligature", "\ufb01", NFKC, "fi"},
+		{"nfkd folds circled digit", "\u2460", NFKD, "1"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := Normalize(tt.in, tt.form); got != tt.want {
+				t.Errorf("Normalize(%q, %s) = %q, want %q", tt.in, tt.form, got, tt.want)
+			}
+		})
+	}
+}
+
+func TestParseNormalization(t *testing.T) {
+	for in, want := range map[string]Normalization{
+		"":     None,
+		"nfc":  NFC,
+		" NFD": NFD,
+		"nfkc": NFKC,
+		"NFKD": NFKD,
+	} {
+		got, err := ParseNormalization(in)
+		if err != nil {
+			t.Errorf("ParseNormalization(%q): %v", in, err)
+			continue
+		}
+		if got != want {
+			t.Errorf("ParseNormalization(%q) = %q, want %q", in, got, want)
+		}
+	}
+	if _, err := ParseNormalization("NFX"); err == nil {
+		t.Error("ParseNormalization(NFX) succeeded, want error")
+	}
+}
+
+func TestStreamRoundTrip(t *testing.T) {
+	const text = "Grüße aus Köln — こんにちは"
+
+	encoded, err := Encode([]byte(text), "windows-1252")
+	if err != nil {
+		t.Fatalf("Encode: %v", err)
+	}
+
+	r, err := NewReader(bytes.NewReader(encoded), "windows-1252")
+	if err != nil {
+		t.Fatalf("NewReader: %v", err)
+	}
+
+	var buf bytes.Buffer
+	w, err := NewWriter(&buf, "utf-8", None)
+	if err != nil {
+		t.Fatalf("NewWriter: %v", err)
+	}
+	if _, err := io.Copy(w, r); err != nil {
+		t.Fatalf("copy: %v", err)
+	}
+	if err := w.Close(); err != nil {
+		t.Fatalf("Close: %v", err)
+	}
+	if got := buf.String(); !strings.Contains(got, "Grüße") {
+		t.Errorf("round trip lost data: %q", got)
+	}
+}

