package textconv

import (
	"fmt"
	"strings"

	"golang.org/x/text/unicode/norm"
)

// Normalization identifies a Unicode normalization form.
type Normalization string

const (
	// None disables normalization.
	None Normalization = ""
	// NFC is Canonical Composition.
	NFC Normalization = "NFC"
	// NFD is Canonical Decomposition.
	NFD Normalization = "NFD"
	// NFKC is Compatibility Composition.
	NFKC Normalization = "NFKC"
	// NFKD is Compatibility Decomposition.
	NFKD Normalization = "NFKD"
)

// ParseNormalization converts a case-insensitive form name ("NFC", "nfkd",
// ...) into a Normalization. An empty name yields None.
func ParseNormalization(name string) (Normalization, error) {
	switch strings.ToUpper(strings.TrimSpace(name)) {
	case "":
		return None, nil
	case "NFC":
		return NFC, nil
	case "NFD":
		return NFD, nil
	case "NFKC":
		return NFKC, nil
	case "NFKD":
		return NFKD, nil
	default:
		return None, fmt.Errorf("textconv: unknown normalization form %q", name)
	}
}

// form maps a Normalization to its norm.Form. None maps to NFC, which is a
// no-op when normalization is disabled.
func (n Normalization) form() norm.Form {
	switch n {
	case NFD:
		return norm.NFD
	case NFKC:
		return norm.NFKC
	case NFKD:
		return norm.NFKD
	default:
		return norm.NFC
	}
}

// Normalize returns s normalized to form n. It returns s unchanged when n is
// None.
func Normalize(s string, n Normalization) string {
	if n == None {
		return s
	}
	return n.form().String(s)
}
