	"golang.org/x/text/encoding/traditionalchinese"
	"golang.org/x/text/unicode"
)

// encodings maps canonical, lower-case encoding names to their implementations.
// Names use hyphens; Lookup normalizes other spellings before consulting it.
var encodings = map[string]encoding.Encoding{
	"utf-8":        unicode.UTF8,
	"utf-16":       unicode.UTF16(unicode.BigEndian, unicode.UseBOM),
	"utf-16be":     unicode.UTF16(unicode.BigEndian, unicode.IgnoreBOM),
	"utf-16le":     unicode.UTF16(unicode.LittleEndian, unicode.IgnoreBOM),
	"iso-8859-1":   charmap.ISO8859_1,
	"iso-8859-15":  charmap.ISO8859_15,
	"windows-1252": charmap.Windows1252,
	"koi8-r":       charmap.KOI8R,
	"macintosh":    charmap.Macintosh,
	"cp437":        charmap.CodePage437,
	"shift-jis":    japanese.ShiftJIS,
	"euc-jp":       japanese.EUCJP,
	"iso-2022-jp":  japanese.ISO2022JP,
	"euc-kr":       korean.EUCKR,
	"gbk":          simplifiedchinese.GBK,
	"gb18030":      simplifiedchinese.GB18030,
	"hz-gb2312":    simplifiedchinese.HZGB2312,
	"big5":         traditionalchinese.Big5,
}

// encodingAliases resolves common alternative spellings to canonical names.
// Keys are compared after normalizeName is applied.
var encodingAliases = map[string]string{
	"utf8":          "utf-8",
	"utf16":         "utf-16",
	"utf16be":       "utf-16be",
	"utf16le":       "utf-16le",
	"unicode":       "utf-16le",
	"latin1":        "iso-8859-1",
	"latin-1":       "iso-8859-1",
	"iso8859-1":     "iso-8859-1",
	"latin9":        "iso-8859-15",
	"cp1252":        "windows-1252",
	"windows1252":   "windows-1252",
	"cp932":         "shift-jis",
	"sjis":          "shift-jis",
	"shiftjis":      "shift-jis",
	"cp949":         "euc-kr",
	"cp936":         "gbk",
	"cp950":         "big5",
	"koi8r":         "koi8-r",
	"mac":           "macintosh",
	"mac-roman":     "macintosh",
	"ibm437":        "cp437",
	"iso2022-jp":    "iso-2022-jp",
	"hzgb2312":      "hz-gb2312",
}

// Lookup returns the encoding registered under name. Matching is
// case-insensitive and ignores underscores, so "UTF_8", "utf-8" and "utf8" all
// resolve to the same encoding.
func Lookup(name string) (encoding.Encoding, error) {
	key := normalizeName(name)
	if enc, ok := encodings[key]; ok {
		return enc, nil
	}
	if canonical, ok := encodingAliases[key]; ok {
		return encodings[canonical], nil
	}
	return nil, fmt.Errorf("textconv: unknown encoding %q", name)
}

// Names returns the sorted list of canonical encoding names.
func Names() []string {
	names := make([]string, 0, len(encodings))
	for name := range encodings {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func normalizeName(name string) string {
	name = strings.ToLower(strings.TrimSpace(name))
	return strings.ReplaceAll(name, "_", "-")
}

package textconv

import (
	"fmt"
	"strings"

	"golang.org/x/text/unicode/norm"
)

// Normalization identifies a Unicode normalization form.
type Normalization string

const (
	// None disables normalization.
	None Normalization = ""
	// NFC is Unicode Normalization Form C (canonical composition).
	NFC Normalization = "NFC"
	// NFD is Unicode Normalization Form D (canonical decomposition).
	NFD Normalization = "NFD"
	// NFKC is Unicode Normalization Form KC (compatibility composition).
	NFKC Normalization = "NFKC"
	// NFKD is Unicode Normalization Form KD (compatibility decomposition).
	NFKD Normalization = "NFKD"
)

// ParseNormalization converts a case-insensitive form name such as "NFC" or
// "nfkd" into a Normalization. An empty name yields None.
func ParseNormalization(name string) (Normalization, error) {
	switch strings.ToUpper(strings.TrimSpace(name)) {
	case "":
		return None, nil
	case "NFC":
		return NFC, nil
	case "NFD":
		return NFD, nil
	case "NFKC":
		return NFKC, nil
	case "NFKD":
		return NFKD, nil
	default:
		return None, fmt.Errorf("textconv: unknown normalization form %q", name)
	}
}

// form maps a Normalization onto its norm.Form. None maps to NFC, which is
// harmless because callers check for None before normalizing.
func (n Normalization) form() norm.Form {
	switch n {
	case NFD:
		return norm.NFD
	case NFKC:
		return norm.NFKC
	case NFKD:
		return norm.NFKD
	default:
		return norm.NFC
	}
}

// Normalize returns s normalized to form n. It returns s unchanged when n is
// None.
func Normalize(s string, n Normalization) string {
	if n == None {
		return s
	}
	return n.form().String(s)
}

// Package textconv converts text between character encodings and applies
// Unicode normalization.
//
// It builds on golang.org/x/text: decoding turns bytes in a source encoding
// into UTF-8, normalization operates on that UTF-8, and encoding turns UTF-8
// into the destination encoding.
package textconv

import (
	"fmt"
	"io"

	"golang.org/x/text/encoding"
	"golang.org/x/text/transform"
)

// Decode converts data from the named source encoding into UTF-8. Invalid
// input sequences are replaced with U+FFFD.
func Decode(data []byte, src string) ([]byte, error) {
	enc, err := Lookup(src)
	if err != nil {
		return nil, err
	}
	return decode(data, enc)
}

func decode(data []byte, enc encoding.Encoding) ([]byte, error) {
	out, _, err := transform.Bytes(enc.NewDecoder(), data)
	if err != nil {
		return nil, fmt.Errorf("textconv: decode: %w", err)
	}
	return out, nil
}

// Encode converts UTF-8 text into the named destination encoding. Runes that
// cannot be represented are replaced with the encoding's substitution, usually
// '?'.
func Encode(utf8 []byte, dst string) ([]byte, error) {
	enc, err := Lookup(dst)
	if err != nil {
		return nil, err
	}
	return encode(utf8, enc)
}

func encode(utf8 []byte, enc encoding.Encoding) ([]byte, error) {
	out, _, err := transform.Bytes(enc.NewEncoder(), utf8)
	if err != nil {
		return nil, fmt.Errorf("textconv: encode: %w", err)
	}
	return out, nil
}

// Convert decodes data from the from encoding, normalizes it to n (when n is
// not None), and encodes the result as to.
func Convert(data []byte, from, to string, n Normalization) ([]byte, error) {
	utf8, err := Decode(data, from)
	if err != nil {
		return nil, err
	}
	if n != None {
		utf8 = []byte(Normalize(string(utf8), n))
	}
	return Encode(utf8, to)
}

// NewReader returns a reader that decodes the underlying stream from src into
// UTF-8.
func NewReader(r io.Reader, src string) (io.Reader, error) {
	enc, err := Lookup(src)
	if err != nil {
		return nil, err
	}
	return transform.NewReader(r, enc.NewDecoder()), nil
}

// NewWriter returns a writer that normalizes UTF-8 input to n and encodes it
// as dst before writing to w. Callers must call Close to flush trailing bytes.
func NewWriter(w io.Writer, dst string, n Normalization) (io.WriteCloser, error) {
	enc, err := Lookup(dst)
	if err != nil {
		return nil, err
	}
	if n == None {
		return transform.NewWriter(w, enc.NewEncoder()), nil
	}
	return transform.NewWriter(w, transform.Chain(n.form(), enc.NewEncoder())), nil
}

// Command textconv converts text between character encodings and applies
// Unicode normalization.
//
// Usage:
//
//	textconv -from windows-1252 -to utf-8 -normalize NFC [file]
//
// With no file, or with "-", it reads from standard input and writes to
// standard output.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"

	"example.com/textconv"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "textconv:", err)
		os.Exit(1)
	}
}

func run() error {
	from := flag.String("from", "utf-8", "source encoding")
	to := flag.String("to", "utf-8", "destination encoding")
	form := flag.String("normalize", "", "Unicode normalization form (NFC, NFD, NFKC, NFKD)")
	list := flag.Bool("list", false, "list supported encodings and exit")
	flag.Parse()

	if *list {
		for _, name := range textconv.Names() {
			fmt.Println(name)
		}
		return nil
	}

	n, err := textconv.ParseNormalization(*form)
	if err != nil {
		return err
	}

	in, err := openInput(flag.Arg(0))
	if err != nil {
		return err
	}
	defer in.Close()

	src, err := textconv.NewReader(in, *from)
	if err != nil {
		return err
	}

	dst, err := textconv.NewWriter(os.Stdout, *to, n)
	if err != nil {
		return err
	}

	if _, err := io.Copy(dst, src); err != nil {
		return err
	}
	return dst.Close()
}

func openInput(path string) (io.ReadCloser, error) {
	if path == "" || path == "-" {
		return io.NopCloser(os.Stdin), nil
	}
	return os.Open(path)
}

